using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class SceneTabsOperations:RefCounted
{
    private readonly TimelineEditorOperations _editor=new();private readonly ActorDataOperations _data=new();private const string AudioSceneUid="kiwi_audio_scene_uid";
    private static GArray Documents(TabBar owner)=>owner.Get("documents").AsGodotArray();private static Control? Timeline(TabBar owner)=>owner.Get("timeline").As<Control>();private static int Active(TabBar owner)=>owner.Get("_active_index").AsInt32();private static Control? Workspace(TabBar owner,string name)=>owner.Get(name+"_workspace").As<Control>();private static string Kind(Settings document)=>document.GetValueOrDefault("type","scene").AsString();
    private static Resource NewResource(string path)=>GD.Load<GDScript>(path).New().As<Resource>();
    public void tab_selected(TabBar owner,int index){if(owner.Get("_switching").AsBool()||Timeline(owner)==null||index<0||index>=Documents(owner).Count){if(!owner.Get("_switching").AsBool()&&Timeline(owner)!=null&&index==Documents(owner).Count)owner.Call("_show_new_tab_menu");return;}capture_current(owner);open_index(owner,index);}
    public void open_index(TabBar owner,int index)
    {
        var timeline=Timeline(owner);var documents=Documents(owner);if(timeline==null||index<0||index>=documents.Count)return;owner.Set("_switching",true);owner.CurrentTab=index;var document=documents[index].AsGodotDictionary();foreach(string name in new[]{"audio","model","environment","transformation","compositing"}){var workspace=Workspace(owner,name);if(workspace!=null)workspace.Visible=false;}string kind=Kind(document);bool scene=kind is not ("shader" or "image" or "audio" or "model" or "environment" or "transformation" or "compositing");foreach(string name in new[]{"scene","shader","image"}){var workspace=Workspace(owner,name);if(workspace!=null)workspace.Visible=name=="scene"?scene:name==kind;}if(scene){owner.Set("_audio_scene_id",document.GetValueOrDefault("id","").AsString());_editor.restore_scene_data(timeline,document["scene"].As<Resource>(),true);var model=timeline.Get("model").As<RefCounted>();var fresh=model.Get("history").As<UndoRedo>();var retained=document["history"].As<UndoRedo>();if(fresh!=retained){fresh.ClearHistory();fresh.Free();}model.Set("history",retained);}else{var workspace=Workspace(owner,kind);if(workspace==null)throw new InvalidOperationException("Workspace is unavailable: "+kind);workspace.Visible=true;var state=document.GetValueOrDefault("state",new Settings()).AsGodotDictionary();if(kind=="shader"){var binding=document.GetValueOrDefault("binding",new Settings()).AsGodotDictionary();if(state.GetValueOrDefault("parameters_linked",false).AsBool()){var linked=owner.Call("_read_linked_shader_parameters",binding);if(linked.VariantType==Variant.Type.Dictionary)state["parameters"]=linked.AsGodotDictionary().Duplicate(true);document["state"]=state;documents[index]=document;}workspace.Call("open_source",document["source"],state,binding);}else{workspace.Call("open_source",document["source"],state);if(kind=="audio"){var session=workspace.Get("session").AsGodotObject();var composition=session.Get("document").AsGodotObject();workspace.Call("set_scene_binding",composition.Get("scene_binding").AsGodotDictionary().Count>0);workspace.Get("send_scene_button").As<Button>().TooltipText="Save the editable composition before sending, then save the destination scene. The Scene Edit Audio command can reopen the composition after restart. Moving either saved file requires relinking.";}}}owner.Set("_active_index",index);owner.Set("_switching",false);refresh_titles(owner);
    }
    public void capture_current(TabBar owner)
    {
        var documents=Documents(owner);int index=Active(owner);var timeline=Timeline(owner);if(owner.Get("_switching").AsBool()||timeline==null||index<0||index>=documents.Count)return;var document=documents[index].AsGodotDictionary();string kind=Kind(document);if(kind is "environment" or "compositing" or "transformation" or "model"){var workspace=Workspace(owner,kind);if(workspace==null)return;document["state"]=workspace.Call("capture_state");document["path"]=workspace.Get("path");document["dirty"]=kind=="compositing"?workspace.Get("dirty"):workspace.Get("session").AsGodotObject().Get("dirty");if(kind=="compositing"){document["source"]=workspace.Get("source");document["identity"]=compositing_identity(document["source"]);}}else if(kind is "shader" or "image" or "audio"){var workspace=Workspace(owner,kind);if(workspace!=null){var state=workspace.Call("capture_state").AsGodotDictionary();document["state"]=state;document["source"]=kind=="shader"?state["source"]:workspace.Get("source");document["path"]=kind=="shader"?state["path"]:workspace.Get("path");document["identity"]=kind=="shader"?shader_identity(document["source"]):kind=="image"?image_identity(document["source"]):owner.Call("_audio_identity",document["source"]);}}else{var scene=_editor.capture_scene_data(timeline,false);scene.SetMeta(AudioSceneUid,document.GetValueOrDefault("persistent_id","").AsString());document["scene"]=scene;document["history"]=timeline.Get("model").AsGodotObject().Get("history");}documents[index]=document;
    }
    public void active_scene_changed(TabBar owner){int index=Active(owner);var documents=Documents(owner);if(owner.Get("_switching").AsBool()||index<0||index>=documents.Count)return;var document=documents[index].AsGodotDictionary();if(Kind(document)!="scene")return;document["dirty"]=true;documents[index]=document;refresh_titles(owner);}
    public void add_document(TabBar owner,Resource scene,string path,string title,UndoRedo history){string persistent=scene.GetMeta(AudioSceneUid,"").AsString();bool saved=path.Length>0&&persistent.Length>0&&persistent.EnumerateRunes().Count()<=128;if(persistent.Length==0||persistent.EnumerateRunes().Count()>128)persistent=_data.new_id();scene.SetMeta(AudioSceneUid,persistent);Documents(owner).Add(new Settings{["id"]=_data.new_id(),["persistent_id"]=persistent,["persistent_saved"]=saved,["type"]="scene",["scene"]=scene,["path"]=path,["name"]=title,["history"]=history,["dirty"]=false});owner.Set("_switching",true);owner.AddTab(title,GD.Load<Texture2D>("res://Workspaces/SceneWorkspace/Icon.png"));if(owner.TabCount>Documents(owner).Count)owner.MoveTab(owner.TabCount-1,Documents(owner).Count-1);ensure_new_tab(owner);owner.Set("_switching",false);}
    public void ensure_new_tab(TabBar owner){int count=Documents(owner).Count;if(owner.TabCount==count)owner.AddTab("",GD.Load<Texture2D>("res://resources/Images/BasicImages/Plus.png"));owner.SetTabTooltip(count,"Create a scene, model, shader, image, audio, transformation, or composition tab");}
    public Resource blank_scene(){var scene=new ActorSceneData();var section=new ActorSection();scene.Get("sections").AsGodotArray().Add(section);scene.Set("selected_section_id",section.Get("id"));scene.Set("inspector_state",new ActorInspectorState());return scene;}
    public string new_untitled_name(TabBar owner){int count=owner.Get("_untitled_counter").AsInt32();owner.Set("_untitled_counter",count+1);return "Untitled "+count;}
    public void new_scene(TabBar owner){if(Timeline(owner)==null)return;capture_current(owner);add_document(owner,blank_scene(),"",new_untitled_name(owner),new UndoRedo());open_index(owner,Documents(owner).Count-1);}
    public void refresh_titles(TabBar owner){var documents=Documents(owner);for(int i=0;i<Math.Min(documents.Count,owner.TabCount);i++){var document=documents[i].AsGodotDictionary();owner.SetTabTitle(i,document["name"].AsString()+(document.GetValueOrDefault("dirty",false).AsBool()?"  •":""));string path=document.GetValueOrDefault("path","").AsString();owner.SetTabTooltip(i,path.Length>0?path:"Unsaved "+Kind(document));}}
    public string shader_identity(Variant source)=>source.VariantType==Variant.Type.String?source.AsString().Replace('\\','/').SimplifyPath():source.VariantType==Variant.Type.Object&&source.AsGodotObject() is Shader shader?"embedded:"+shader.GetInstanceId():"";
    public string image_identity(Variant value){if(value.VariantType==Variant.Type.String){string normalized=value.AsString().Replace('\\','/').SimplifyPath();if(FileAccess.FileExists(normalized+".image.tres"))normalized+=".image.tres";return ProjectSettings.GlobalizePath(normalized).Replace('\\','/').SimplifyPath();}return value.VariantType==Variant.Type.Object&&value.AsGodotObject() is GodotObject resource?"embedded:"+resource.GetInstanceId():"";}
    public string compositing_identity(Variant value){if(value.VariantType==Variant.Type.String)return ProjectSettings.GlobalizePath(value.AsString()).Replace('\\','/').SimplifyPath();var resource=value.VariantType==Variant.Type.Object?value.AsGodotObject() as Resource:null;return resource is CompositingDocument||ActorDataOperations.ScriptIs(resource,"res://Workspaces/CompositingWorkspace/compositing_document.gd")?"embedded:"+resource!.GetInstanceId():"";}
    public string current_scene_path(TabBar owner){int index=Active(owner);var documents=Documents(owner);return index>=0&&index<documents.Count&&Kind(documents[index].AsGodotDictionary())=="scene"?documents[index].AsGodotDictionary()["path"].AsString():"";}
    public string current_scene_name(TabBar owner){int index=Active(owner);var documents=Documents(owner);return index>=0&&index<documents.Count?documents[index].AsGodotDictionary()["name"].AsString():"New Scene";}
    public int save_current(TabBar owner,string path){var timeline=Timeline(owner);var documents=Documents(owner);int index=Active(owner);if(timeline==null||index<0||index>=documents.Count||Kind(documents[index].AsGodotDictionary())!="scene")return (int)Error.Unavailable;capture_current(owner);var document=documents[index].AsGodotDictionary();string destination=path.Length>0?path:document["path"].AsString();if(destination.Length==0)return (int)Error.FileBadPath;var scene=_editor.capture_scene_data(timeline,true);scene.ResourceName=destination.GetFile().GetBaseName();scene.SetMeta(AudioSceneUid,document.GetValueOrDefault("persistent_id","").AsString());var error=ResourceSaver.Save(scene,destination);if(error!=Error.Ok)return (int)error;string previous=document["path"].AsString();document["path"]=destination;document["persistent_saved"]=true;document["name"]=destination.GetFile().GetBaseName();document["dirty"]=false;documents[index]=document;owner.Call("_relocate_audio_associations",document.GetValueOrDefault("persistent_id","").AsString(),previous,destination);refresh_titles(owner);var filesystem=GD.Load<GDScript>("res://scripts/Globals/local_project_filesystem.gd");if(filesystem.Get("node").AsGodotObject()!=null)filesystem.Call("update_root_folder");return (int)Error.Ok;}
}
